from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
for c in ['00455','00558','00544','00592','00593']:
 d=json.loads((R/f'data/patient-knowledge/{c}.json').read_text());esc=html.escape
 lung_scope='non-small-cell lung cancer' if c in ['00455','00558'] else 'lung cancer'
 body=f'''<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Choose treatment context · NCCP {c} · SACTCheck</title><link rel="stylesheet" href="../../assets/patient/patient-regimen-page-v0819.css"><link rel="stylesheet" href="../../assets/patient/patient-knowledge.css"></head><body><main class="pk-shell"><section class="pk-section"><div class="pk-eyebrow">NCCP {c}</div><h1>Match the information to your treatment.</h1><p>This medicine is used for several cancers. These patient materials cover {lung_scope} only. Your team confirms the exact indication, treatment aim and schedule.</p><article class="pk-card"><h2>{esc(d['title'])}</h2><p>{esc(d.get('scope_note',d.get('indication_text',d['context_label'])))}</p><p>{esc(d['schedule_summary'])}</p><a class="pk-button" id="lung-material" href="./">Open the lung treatment information</a></article><article class="pk-card"><h2>Another cancer or combination regimen</h2><p>Use the matching regimen and indication for other cancers or combination treatment. A schedule, treatment limit or evidence result from one setting may not apply to another.</p><a href="{esc(d['sources'][0]['url'])}">Open the shared NCCP regimen</a></article><p>Source reconciled; independent clinical, pharmacy and patient/PPI review pending · SACTCheck v0.84.26</p><p><a href="../../">Return to SACTCheck</a></p></section></main><script src="../../assets/patient/lung-indication-scope-v08426.js"></script></body></html>\n'''
 (R/f'patient/{c}/scope.html').write_text(body)
print('Five shared-protocol lung scope gates refreshed.')
